local function RequestState(requested)
	local actual = 0
	if state_changing ~= 0 then
		state_desired = requested
		return
	end
	state_changing = 1
	actual = state_desired
	state_desired = requested
	while state_desired ~= actual do
		if state_desired == 0 then
			activatescr()
			actual = 0
		end
		if state_desired == 1 then
			deactivatescr()
			actual = 1
		end
	end
	state_changing = 0
end

function script.Create()
